 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    obj = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    marks = [(r,c,grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] not in (0,8)]
    if not obj or not marks:
        return [row[:] for row in grid]
    # The marker is a color inventory: each colored marker cell represents
    # one block of the same size in the large 8-shaped figure.
    r0,r1=min(r for r,c in obj),max(r for r,c in obj)
    c0,c1=min(c for r,c in obj),max(c for r,c in obj)
    mr0,mr1=min(r for r,c,v in marks),max(r for r,c,v in marks)
    mc0,mc1=min(c for r,c,v in marks),max(c for r,c,v in marks)
    th=(r1-r0+1)//(mr1-mr0+1)
    tw=(c1-c0+1)//(mc1-mc0+1)
    # Group marker cells by color and use their multiplicities to color
    # the corresponding number of coarse cells, in marker scan order.
    counts={}
    order=[]
    for r,c,v in marks:
        if v not in counts: counts[v]=0; order.append(v)
        counts[v]+=1
    cells=[]
    for r in range(r0,r1+1,th):
        for c in range(c0,c1+1,tw):
            if grid[r][c]==8: cells.append((r,c))
    out=[row[:] for row in grid]
    k=0
    for color in order:
        for _ in range(counts[color]):
            if k>=len(cells): break
            rr,cc=cells[k]; k+=1
            for r in range(rr,min(rr+th,h)):
                for c in range(cc,min(cc+tw,w)):
                    if grid[r][c]==8: out[r][c]=color
    return out
